      tokenId: reward.tokenAddress,
      symbol: reward.symbol,
      name: reward.symbol,
      // On-chain doesn't have name, use symbol
      decimals: reward.decimals,
      rawAmount: reward.amount,
      amount: reward.amountFormatted,
      usdAmount
