"use strict";
import { useMemo } from "react";
import { useReadContracts, useChainId } from "wagmi";
import { formatUnits } from "viem";
import { getContractAddress, getContractAbi } from "uniswap/src/constants/contracts";
import { useVotedLocks } from "./useVotedLocks";
export function useUserVotesForAllPools(poolAddresses, userLocks) {
  const chainId = useChainId();
  const voterAddress = getContractAddress(chainId, "Voter");
  const voterAbi = getContractAbi(chainId, "Voter");
  const votingEscrowAddress = getContractAddress(chainId, "VotingEscrow");
  const votingEscrowAbi = getContractAbi(chainId, "VotingEscrow");
  const { votedLockIds, isLoading: votedLocksLoading } = useVotedLocks(userLocks || []);
  const votedLockIdsArray = useMemo(() => Array.from(votedLockIds).sort(), [votedLockIds]);
  const votedLockIdsKey = votedLockIdsArray.join(",");
  const votedLocks = useMemo(() => {
    return (userLocks || []).filter((lock) => votedLockIds.has(lock.id));
  }, [userLocks, votedLockIdsKey]);
  const votedLocksKey = useMemo(() => votedLocks.map((l) => l.id).sort().join(","), [votedLocks]);
  const poolAddressesKey = useMemo(() => poolAddresses.join(","), [poolAddresses]);
  const contracts = useMemo(() => {
    if (!votedLocks.length || !poolAddresses.length) return [];
    const calls = [];
    votedLocks.forEach((lock) => {
      calls.push({
        address: votingEscrowAddress,
        abi: votingEscrowAbi,
        functionName: "balanceOfNFT",
        args: [BigInt(lock.id)],
        meta: { type: "balance", lockId: lock.id }
      });
      calls.push({
        address: voterAddress,
        abi: voterAbi,
        functionName: "usedWeights",
        args: [BigInt(lock.id)],
        meta: { type: "usedWeights", lockId: lock.id }
      });
    });
    poolAddresses.forEach((poolAddress) => {
      calls.push({
        address: voterAddress,
        abi: voterAbi,
        functionName: "weights",
        args: [poolAddress],
        meta: { type: "poolWeight", poolAddress }
      });
    });
    votedLocks.forEach((lock) => {
      poolAddresses.forEach((poolAddress) => {
        calls.push({
          address: voterAddress,
          abi: voterAbi,
          functionName: "votes",
          args: [BigInt(lock.id), poolAddress],
          meta: { type: "vote", lockId: lock.id, poolAddress }
        });
      });
    });
    return calls;
  }, [votedLocks, poolAddressesKey, voterAddress, votingEscrowAddress]);
  const { data, isLoading: contractsLoading } = useReadContracts({
    contracts,
    query: {
      enabled: contracts.length > 0,
      staleTime: 3e4,
      // 30 seconds
      refetchInterval: 6e4,
      // 1 minute
      refetchOnWindowFocus: false
    }
  });
  const votesMap = useMemo(() => {
    const map = /* @__PURE__ */ new Map();
    if (!data || contractsLoading || votedLocksLoading || !votedLocks.length) {
      return map;
    }
    const lockData = /* @__PURE__ */ new Map();
    votedLocks.forEach((lock, index) => {
      const balanceIndex = index * 2;
      const usedWeightsIndex = index * 2 + 1;
      const balance = data[balanceIndex]?.result;
      const usedWeights = data[usedWeightsIndex]?.result;
      if (balance && usedWeights && usedWeights > 0n) {
        lockData.set(lock.id, { balance, usedWeights });
      }
    });
    const poolWeightStartIndex = votedLocks.length * 2;
    const poolWeights = /* @__PURE__ */ new Map();
    poolAddresses.forEach((poolAddress, index) => {
      const poolWeight = data[poolWeightStartIndex + index]?.result;
      if (poolWeight && poolWeight > 0n) {
        poolWeights.set(poolAddress, poolWeight);
      }
    });
    const voteStartIndex = votedLocks.length * 2 + poolAddresses.length;
    let voteIndex = voteStartIndex;
    votedLocks.forEach((lock) => {
      const lockInfo = lockData.get(lock.id);
      if (!lockInfo) return;
      poolAddresses.forEach((poolAddress) => {
        const poolVotes = data[voteIndex]?.result;
        voteIndex++;
        if (poolVotes && poolVotes > 0n) {
          const poolTotalWeight = poolWeights.get(poolAddress) || 0n;
          const percentage = poolTotalWeight > 0n ? Number(poolVotes * 10000n / poolTotalWeight) / 100 : 0;
          const veAbxRaw = poolVotes * lockInfo.balance / lockInfo.usedWeights;
          const veAbxFormatted = formatUnits(veAbxRaw, 18);
          const veAbxFloat = parseFloat(veAbxFormatted);
          let veAbxAmount;
          if (veAbxFloat === 0) {
            veAbxAmount = "0";
          } else if (veAbxFloat < 0.01) {
            veAbxAmount = "< 0.01";
          } else if (veAbxFloat < 1) {
            veAbxAmount = veAbxFloat.toFixed(4);
          } else if (veAbxFloat < 1e3) {
            veAbxAmount = veAbxFloat.toFixed(2);
          } else if (veAbxFloat < 1e6) {
            veAbxAmount = (veAbxFloat / 1e3).toFixed(2) + "K";
          } else {
            veAbxAmount = (veAbxFloat / 1e6).toFixed(2) + "M";
          }
          const voteInfo = {
            lockId: lock.id,
            lockIdShort: `#${lock.id.slice(-6)}`,
            percentage: Math.round(percentage * 100) / 100,
            veAbxAmount,
            veAbxRaw
          };
          const existing = map.get(poolAddress) || [];
          map.set(poolAddress, [...existing, voteInfo]);
        }
      });
    });
    return map;
  }, [data, contractsLoading, votedLocksLoading, votedLocksKey, poolAddressesKey]);
  return {
    votesMap,
    isLoading: contractsLoading || votedLocksLoading
  };
}
