const V2_FACTORY_FEE_ABI = [
  {
    inputs: [
      { name: "_pool", type: "address" },
      { name: "_stable", type: "bool" }
    ],
    name: "getFee",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
const V3_POOL_FEE_ABI = [
  {
    inputs: [],
    name: "fee",
    outputs: [{ name: "", type: "uint24" }],
    stateMutability: "view",
    type: "function"
  }
];
export function usePoolWeightsAndFees(chainId, pools) {
  const voterAddress = getContractAddress(chainId, "Voter");
  const voterAbi = getContractAbi(chainId, "Voter");
  const abstractContracts = getAbstractContracts(chainId);
  const factoryAddress = abstractContracts?.poolFactory;
  const contracts = useMemo(() => {
    if (!voterAddress || !factoryAddress || pools.length === 0) return [];
    const calls = [];
    pools.forEach((pool) => {
      calls.push({
        address: voterAddress,
        abi: voterAbi,
        functionName: "weights",
        args: [pool.poolAddress]
      });
      if (pool.poolType === "V2") {
        calls.push({
          address: factoryAddress,
          abi: V2_FACTORY_FEE_ABI,
          functionName: "getFee",
          args: [pool.poolAddress, pool.stable ?? false]
        });
      } else {
        calls.push({
          address: pool.poolAddress,
          abi: V3_POOL_FEE_ABI,
          functionName: "fee",
          args: []
        });
      }
    });
    calls.push({
      address: voterAddress,
      abi: voterAbi,
      functionName: "totalWeight",
      args: []
    });
    return calls;
  }, [voterAddress, voterAbi, factoryAddress, pools]);
  const { data: results, isLoading } = useReadContracts({
    contracts,
    query: {
      enabled: contracts.length > 0,
      staleTime: 5 * 60 * 1e3,
      // 5 minutes
      gcTime: 10 * 60 * 1e3
      // 10 minutes
    }
  });
  const { weights, fees, totalWeight } = useMemo(() => {
    const weightMap = /* @__PURE__ */ new Map();
    const feeMap = /* @__PURE__ */ new Map();
    let total = 0;
    if (!results || results.length === 0) {
      return { weights: weightMap, fees: feeMap, totalWeight: total };
    }
    pools.forEach((pool, index) => {
      const weightResult = results[index * 2];
      const feeResult = results[index * 2 + 1];
      const poolKey = pool.poolAddress.toLowerCase();
      if (weightResult?.status === "success" && weightResult.result !== void 0) {
        weightMap.set(poolKey, Number(weightResult.result) / 1e18);
      }
      if (feeResult?.status === "success" && feeResult.result !== void 0) {
        const feeValue = Number(feeResult.result);
        const feeInPips = pool.poolType === "V2" ? feeValue * 100 : feeValue;
        feeMap.set(poolKey, feeInPips);
      }
    });
    const totalWeightResult = results[results.length - 1];
    if (totalWeightResult?.status === "success" && totalWeightResult.result !== void 0) {
      total = Number(totalWeightResult.result) / 1e18;
    }
    return { weights: weightMap, fees: feeMap, totalWeight: total };
  }, [results, pools]);
  return {
    weights,
    fees,
    totalWeight,
    isLoading
  };
}
