"use strict";
import { useAccount } from "hooks/useAccount";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useEffect, useRef } from "react";
import { ChevronLeft, ChevronRight } from "react-feather";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { selectPendingVotes, selectSelectedLock, setSelectedLock } from "state/voting/slice";
import { Navigation, Pagination } from "swiper/modules";
import { Swiper, SwiperSlide } from "swiper/react";
import { Flex, Text, styled as UiStyled, useIsDarkMode, useMedia, useSporeColors } from "ui/src";
import { calculateTimeUntilUnlock } from "utils/lockCalculations";
import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/pagination";
import SingleSlide from "./SingleSlide";
import VoteBottomSliderLoader from "./VoteBottomSliderLoader";
const NavButton = UiStyled(Flex, {
  row: true,
  alignItems: "center",
  justifyContent: "center",
  width: 35,
  height: "100%",
  borderRadius: "$rounded8",
  backgroundColor: "$surface1",
  borderWidth: 1,
  borderColor: "$surface3Hovered",
  cursor: "pointer",
  position: "relative",
  hoverStyle: {
    backgroundColor: "$surface1Hovered"
  },
  $lg: {
    position: "absolute",
    borderColor: "$surface3Hovered",
    backgroundColor: "$surface2",
    borderRadius: "$roundedFull",
    height: 26,
    width: 26
  }
});
const SwiperWrapper = UiStyled(Flex, {
  width: "100%",
  height: "auto"
});
const Slider = ({ lockStatuses, votingStatusSummary }) => {
  const media = useMedia();
  const account = useAccount();
  const dispatch = useAppDispatch();
  const selectedLock = useAppSelector(selectSelectedLock);
  const pendingVotes = useAppSelector(selectPendingVotes);
  const colors = useSporeColors();
  const isDarkMode = useIsDarkMode();
  const { data: userLocks, isLoading } = useVeABXUserLocks(account.address);
  const locksCards = userLocks?.filter((lock) => {
    const isOwner = lock.owner.toLowerCase() === account.address?.toLowerCase();
    const isNotExpired = lock.permanent || !calculateTimeUntilUnlock(lock.lockEnd).expired;
    return isOwner && isNotExpired;
  }) || [];
  const swiperRef = useRef(null);
  const spaceBetween = media.md ? 0 : 10;
  const slidesPerView = media.md ? 1 : 2;
  useEffect(() => {
    if (selectedLock && locksCards.length > 0 && swiperRef.current) {
      const selectedIndex = locksCards.findIndex((lock) => lock.id === selectedLock.id);
      if (selectedIndex !== -1) {
        swiperRef.current.slideTo(selectedIndex);
      }
    }
  }, [selectedLock?.id, locksCards.length]);
  const handlePrev = () => {
    if (swiperRef.current) {
      swiperRef.current.slidePrev();
    }
  };
  const handleNext = () => {
    if (swiperRef.current) {
      swiperRef.current.slideNext();
    }
  };
  if (isLoading) {
    return <VoteBottomSliderLoader />;
  }
  if (locksCards.length === 0) {
    return <Flex row gap={"$spacing16"} flex={1} justifyContent="center" alignItems="center">
        <Text variant="body3" color="$neutral2">
          No locks available. Create a lock to start voting.
        </Text>
      </Flex>;
  }
  const allLocksVoted = votingStatusSummary.unvoted === 0 && votingStatusSummary.total > 0;
  if (allLocksVoted) {
    return <Flex row gap={"$spacing16"} flex={1} justifyContent="center" alignItems="center">
        <Text variant="body4" color="$statusSuccess">
          All {votingStatusSummary.total} lock{votingStatusSummary.total !== 1 ? "s" : ""} successfully voted ✅ Voting
          resets every Thursday.
        </Text>
      </Flex>;
  }
  return <Flex row gap={"$spacing12"} flex={1} justifyContent="flex-start" position="relative" $md={{ px: "$spacing8" }}>
      <NavButton onPress={handlePrev} disabled={locksCards.length <= slidesPerView} $md={{ display: "none" }}>
        <Text>←</Text>
      </NavButton>

      <Flex
    maxWidth={850}
    width={"100%"}
    backgroundColor={isDarkMode ? "$surface2Hovered" : "$surface1Hovered"}
    borderWidth={1}
    borderColor={"$surface3"}
    borderRadius={"$rounded16"}
    boxShadow={"$md"}
    $md={{ padding: "$none", backgroundColor: "$none", borderWidth: "$none" }}
  >
        <SwiperWrapper>
          <Swiper
    modules={[Navigation, Pagination]}
    spaceBetween={spaceBetween}
    slidesPerView={slidesPerView}
    loop={locksCards.length > slidesPerView}
    grabCursor={true}
    navigation={false}
    pagination={false}
    onSwiper={(swiper) => {
      swiperRef.current = swiper;
    }}
    style={{
      width: "100%",
      height: "auto"
    }}
    breakpoints={{
      0: {
        slidesPerView: 1,
        spaceBetween: 10
      },
      768: {
        slidesPerView: 2,
        spaceBetween: 10
      },
      1024: {
        slidesPerView: 2,
        spaceBetween: 10
      }
    }}
  >
            {locksCards.map((lock) => {
    const lockStatus = lockStatuses.find((status) => status.tokenId === lock.id);
    const hasVoted = lockStatus?.hasVoted || false;
    const isSelected = selectedLock?.id === lock.id;
    return <SwiperSlide key={lock.id}>
                  <SingleSlide
      lock={lock}
      isSelected={isSelected}
      selectedPools={isSelected ? pendingVotes.length : 0}
      hasVoted={hasVoted}
      onSelect={() => {
        dispatch(setSelectedLock(lock));
      }}
    />
                </SwiperSlide>;
  })}
          </Swiper>
        </SwiperWrapper>
      </Flex>

      <NavButton onPress={handleNext} disabled={locksCards.length <= slidesPerView} $md={{ display: "none" }}>
        <Text>→</Text>
      </NavButton>

      <NavButton
    onPress={handlePrev}
    disabled={locksCards.length <= slidesPerView}
    left={media.md ? -11 : -4}
    top={"50%"}
    transform={"translateY(-50%)"}
    row
    display="none"
    $md={{ display: "flex" }}
    zIndex={10}
  >
        <ChevronLeft size={media.md ? 20 : 24} color={colors.neutral2.val} />
      </NavButton>
      <NavButton
    onPress={handleNext}
    disabled={locksCards.length <= slidesPerView}
    right={media.md ? -11 : -4}
    top={"50%"}
    transform={"translateY(-50%)"}
    display="none"
    $md={{ display: "flex" }}
    zIndex={10}
  >
        <ChevronRight size={media.md ? 20 : 24} color={colors.neutral2.val} />
      </NavButton>
    </Flex>;
};
export default Slider;
