import { useVoterReadsContext } from "./VoterReadsProvider";
const ResetButton = memo(function ResetButton2({ lockId }) {
  const colors = useSporeColors();
  const { resetVotes } = useVoterContract();
  const { epochStart, epochVoteStart, useLastVoted } = useVoterReadsContext();
  const { data: lastVotedTimestamp } = useLastVoted(lockId);
  const [isResetting, setIsResetting] = useState(false);
  const canResetVote = useMemo(() => {
    if (!lastVotedTimestamp || !epochStart || !epochVoteStart) return false;
    const currentTime = Math.floor(Date.now() / 1e3);
    const DISTRIBUTION_WINDOW = 6 * 60 * 60;
    const lastVoted = Number(lastVotedTimestamp);
    if (epochStart <= lastVoted) {
      return false;
    }
    if (currentTime >= epochStart && currentTime < epochStart + DISTRIBUTION_WINDOW) {
      return false;
    }
    if (currentTime <= epochVoteStart) {
      return false;
    }
    return true;
  }, [epochStart, epochVoteStart, lastVotedTimestamp]);
  const handleResetClick = useCallback(async (e) => {
    e.stopPropagation();
    if (isResetting) return;
    try {
      setIsResetting(true);
      await resetVotes(lockId);
    } catch (error) {
      console.error("Reset votes failed:", error);
    } finally {
      setIsResetting(false);
    }
  }, [isResetting, resetVotes, lockId]);
  if (!canResetVote) return null;
  return <MouseoverTooltip text="Reset votes for this lock" size={TooltipSize.Small} placement="top">
      <Flex
    cursor="pointer"
    onPress={handleResetClick}
    p="$spacing4"
    borderRadius="$rounded4"
    backgroundColor="$surface2"
    hoverStyle={{ backgroundColor: "$surface2Hovered" }}
    opacity={isResetting ? 0.5 : 1}
  >
        {isResetting ? <SpinningLoader size={10} color={colors.neutral2.val} /> : <RotateCcw size={10} color={colors.neutral2.val} />}
      </Flex>
    </MouseoverTooltip>;
});
